def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_scores = [sum(v == 2 for v in row) for row in grid]
    col_scores = [sum(grid[r][c] == 2 for r in range(h)) for c in range(w)]
    # The recurring 2-lines run along one axis; beams run perpendicular to them.
    horizontal_rails = [r for r, score in enumerate(row_scores) if score >= 0.58 * w]
    vertical_rails = [c for c, score in enumerate(col_scores) if score >= 0.58 * h]
    horizontal = len(horizontal_rails) > len(vertical_rails)
    if horizontal:
        rails = horizontal_rails
    else:
        rails = vertical_rails
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3
                    for rr in range(r - 1, r + 2)
                    for cc in range(c - 1, c + 2) if (rr, cc) != (r, c)):
                centers.append((r, c))
    beams = sorted({c if horizontal else r for r, c in centers})
    # Continue each object's beam through the full grid.
    for b in beams:
        if horizontal:
            for r in range(h):
                if out[r][b] == 0:
                    out[r][b] = 1
        else:
            for c in range(w):
                if out[b][c] == 0:
                    out[b][c] = 1
    # Every crossing with a 2-line receives the object's 1-colored ring.
    source_centers = set(centers)
    for rail in rails:
        for beam in beams:
            r, c = (rail, beam) if horizontal else (beam, rail)
            if (r, c) in source_centers:
                continue
            source = next((s for s in centers if (s[1] if horizontal else s[0]) == beam), None)
            one_beam_two_rails = len(beams) == 1 and len(rails) == 2 and source is not None
            for rr in range(max(0, r - 1), min(h, r + 2)):
                for cc in range(max(0, c - 1), min(w, c + 2)):
                    if (rr, cc) == (r, c) or out[rr][cc] == 3:
                        continue
                    # A lone beam meeting one additional rail makes a one-sided stamp
                    # on the approach side; this is the solitary demo's directed case.
                    if one_beam_two_rails:
                        if horizontal and cc != c and rr == r - (1 if source[0] < r else -1):
                            continue
                        if not horizontal and rr != r and cc == c - (1 if source[1] < c else -1):
                            continue
                    out[rr][cc] = 1
    return out
